    /**
     * Custom Mock implementation for Unit of Work to capture and inspect 
     * SObjects registered for creation and their relationships.
     */
    private class MockUnitOfWork implements fflib_ISObjectUnitOfWork {
        public List<SObject> newRecords = new List<SObject>();
        public Map<SObject, Map<String, SObject>> relationships = new Map<SObject, Map<String, SObject>>();
        public Integer commitCount = 0;

        public void registerNew(SObject sObject) {
            newRecords.add(sObject);
        }

        public void registerNew(SObject sObject, String fieldName, SObject relatedTo) {
            newRecords.add(sObject);
            if (!relationships.containsKey(sObject)) {
                relationships.put(sObject, new Map<String, SObject>());
            }
            relationships.get(sObject).put(fieldName, relatedTo);
        }

        public void commitWork() {
            commitCount++;
        }

        public void registerDirty(SObject sObject) {}
        public void registerDeleted(SObject sObject) {}
        public void registerDeleted(SObject sObject, String fieldName, SObject relatedTo) {}
        public void rollbackWork() {}
    }
}
