import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    @api recordId;
    caseListViewUrl;

    async connectedCallback() {
        try {
            // Generate the URL for the "My Open Cases" list view
            this.caseListViewUrl = await this[NavigationMixin.GenerateUrl]({
                type: 'standard__objectPage',
                attributes: {
                    objectApiName: 'Case',
                    actionName: 'list'
                },
                state: {
                    filterName: 'My_Open_Cases'
                }
            });
        } catch (error) {
            console.error('Error generating Case list view URL:', error);
        }
    }

    handleAction(event) {
        const action = event.target.dataset.action;

        switch (action) {
            case 'new-contact':
                this[NavigationMixin.Navigate]({
                    type: 'standard__objectPage',
                    attributes: {
                        objectApiName: 'Contact',
                        actionName: 'new'
                    },
                    state: {
                        defaultFieldValues: encodeDefaultFieldValues({ 
                            AccountId: this.recordId 
                        })
                    }
                });
                break;

            case 'contacts':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordRelationship',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        relationshipName: 'Contacts'
                    },
                    actionName: 'view'
                });
                break;

            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: this.recordId,
                        objectApiName: 'Account',
                        actionName: 'edit'
                    }
                });
                break;
        }
    }
}
