import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    /**
     * Public property for contacts passed from the parent.
     * Expected format: Array of { Id, Name, Title }
     */
    @api contacts;

    /**
     * Determines if the component should render the contact list or the empty state.
     */
    get hasContacts() {
        return this.contacts && this.contacts.length > 0;
    }

    /**
     * Returns the formatted count text based on the number of contacts.
     */
    get countText() {
        const count = this.contacts ? this.contacts.length : 0;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    /**
     * Returns a sorted copy of the contacts array to avoid mutating the @api property.
     * Sorting is performed by Name in ascending order.
     */
    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        return [...this.contacts].sort((a, b) => {
            const nameA = a.Name || '';
            const nameB = b.Name || '';
            return nameA.localeCompare(nameB);
        });
    }
}
