public with sharing class EmployerService {

    /**
     * Sets the current primary employer for a group of contacts.
     * 
     * This method ensures that:
     * 1. A primary, current affiliation is established between the contact and the target Organization account.
     * 2. Any previous primary affiliation is automatically transitioned to 'Former' by NPSP's standard triggers.
     * 3. No duplicate affiliations are created if the target organization is already the primary affiliation.
     * 4. The contact remains associated with their household account.
     * 
     * @param employerByContactId Map where keys are Contact Ids and values are Organization Account Ids.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Query all existing affiliations for the targeted contacts to avoid duplicates 
        // and identify current primary affiliations.
        // This uses 1 SOQL query.
        List<npsp__Affiliation__c> existingAffiliations = [
            SELECT Id, npsp__Contact__c, npsp__Account__c, npsp__Primary__c 
            FROM npsp__Affiliation__c 
            WHERE npsp__Contact__c IN :employerByContactId.keySet()
        ];

        // Map to quickly check the current primary account for a contact
        Map<Id, Id> contactToPrimaryAccountId = new Map<Id, Id>();
        // Map to quickly find if any affiliation already exists between a contact and a specific account
        Map<Id, Map<Id, npsp__Affiliation__c>> contactToAccountMap = new Map<Id, Map<Id, npsp__Affiliation__c>>();

        for (npsp__Affiliation__c aff : existingAffiliations) {
            Id contactId = aff.npsp__Contact__c;

            if (aff.npsp__Primary__c) {
                contactToPrimaryAccountId.put(contactId, aff.npsp__Account__c);
            }

            if (!contactToAccountMap.containsKey(contactId)) {
                contactToAccountMap.put(contactId, new Map<Id, npsp__Affiliation__c>());
            }
            contactToAccountMap.get(contactId).put(aff.npsp__Account__c, aff);
        }

        List<npsp__Affiliation__c> toInsert = new List<npsp__Affiliation__c>();
        List<npsp__Affiliation__c> toUpdate = new List<npsp__Affiliation__c>();

        for (Id contactId : employerByContactId.keySet()) {
            Id targetAccountId = employerByContactId.get(contactId);
            if (targetAccountId == null) {
                continue;
            }

            // Requirement: if the organization already is the contact's primary affiliation, nothing changes.
            Id currentPrimaryAccountId = contactToPrimaryAccountId.get(contactId);
            if (targetAccountId == currentPrimaryAccountId) {
                continue;
            }

            // Check if an affiliation with this account already exists (but isn't primary)
            Map<Id, npsp__Affiliation__c> accountMap = contactToAccountMap.get(contactId);
            if (accountMap != null && accountMap.containsKey(targetAccountId)) {
                npsp__Affiliation__c existingAff = accountMap.get(targetAccountId);
                existingAff.npsp__Primary__c = true;
                existingAff.npsp__Status__c = 'Current';
                toUpdate.add(existingAff);
            } else {
                // Create a new primary affiliation
                npsp__Affiliation__c newAff = new npsp__Affiliation__c(
                    npsp__Contact__c = contactId,
                    npsp__Account__c = targetAccountId,
                    npsp__Primary__c = true,
                    npsp__Status__c = 'Current'
                );
                toInsert.add(newAff);
            }
        }

        // Perform DML operations. NPSP triggers will handle the 'Former' status 
        // and the Contact.npsp__PrimaryAffiliation__c lookup automatically.
        // This uses at most 2 DML statements.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
