/**
 * Service class to handle the staging and processing of one-off gifts
 * using the NPSP Data Import (BDI) engine.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Imports a list of web gifts synchronously using NPSP's BDI engine.
     * 
     * @param gifts List of WebGift data transfer objects.
     * @return List of ImportResult mapping 1:1 to the input list in order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // 1. Stage the NPSP Data Import records
        List<npsp__DataImport__c> stagingRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            stagingRecords.add(new npsp__DataImport__c(
                npsp__First_Name__c = gift.firstName,
                npsp__Last_Name__c = gift.lastName,
                npsp__Email__c = gift.email,
                npsp__Amount__c = gift.amount,
                npsp__Date__c = gift.giftDate
            ));
        }

        // Insert staged records to generate IDs required for processing
        insert stagingRecords;

        try {
            // 2. Process the staged records synchronously via NPSP's Apex API.
            // This applies NPSP matching rules, household creation, and donation processing.
            npsp.BDI.BDIProcess.process(stagingRecords);
        } catch (Exception e) {
            // While BDI processes individual row errors into the npsp__Error__c field,
            // a catastrophic failure (e.g., limit exception) would land here.
            // However, per requirements, we proceed to evaluate results.
        }

        // 3. Re-query the staging records to retrieve the results of the processing.
        // NPSP updates these records with the created/matched Contact, Opportunity, and any Error messages.
        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>([
            SELECT Id, npsp__Contact__c, npsp__Opportunity__c, npsp__Error__c 
            FROM npsp__DataImport__c 
            WHERE Id IN :stagingRecords
        ]);

        // 4. Build the response list maintaining the original input order
        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c stagedRec : stagingRecords) {
            npsp__DataImport__c processedRec = processedMap.get(stagedRec.Id);

            ImportResult res = new ImportResult();
            if (processedRec != null) {
                // NPSP marks success by the absence of an error message
                res.success = String.isBlank(processedRec.npsp__Error__c);
                res.contactId = processedRec.npsp__Contact__c;
                res.opportunityId = processedRec.npsp__Opportunity__c;
                res.errorMessage = processedRec.npsp__Error__c;
            } else {
                res.success = false;
                res.errorMessage = 'Staged record was not found after processing.';
            }
            results.add(res);
        }

        return results;
    }
}
