    /**
     * Custom exception for GAU Allocation errors
     */
    public class AllocationException extends Exception {}

    /**
     * Replaces existing GAU allocations for an Opportunity with new allocations based on percentage.
     * 
     * By populating npsp__Allocation_Percentage__c instead of npsp__Amount__c, 
     * NPSP's internal logic ensures that the allocation amounts are automatically 
     * recalculated whenever the Opportunity amount changes.
