    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // 1. Validate Map presence and content
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('The GAU percentage map cannot be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException('Every GAU percentage must be provided and greater than 0.');
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException('The total percentage allocated cannot exceed 100%.');
        }

