    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Query 1: Fetch Opportunities to validate Primary Contact and Total Amount
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c 
            FROM Opportunity 
            WHERE Id IN :oppIds
        ]);

        // Query 2: Fetch OpportunityContactRoles to verify the specific role exists exactly once per contact
        Map<String, List<OpportunityContactRole>> ocrMap = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role 
            FROM OpportunityContactRole 
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String key = ocr.OpportunityId + '-' + ocr.ContactId;
            if (!ocrMap.containsKey(key)) {
                ocrMap.put(key, new List<OpportunityContactRole>());
            }
            ocrMap.get(key).add(ocr);
        }

        // Query 3: Fetch existing Partial Soft Credits to perform updates instead of inserts
        Map<String, npsp__Partial_Soft_Credit__c> pscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c 
            FROM npsp__Partial_Soft_Credit__c 
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = psc.npsp__Opportunity__c + '-' + psc.npsp__Contact__c;
            pscMap.put(key, psc);
        }

        List<npsp__Partial_Soft_Credit__c> toUpsert = new List<npsp__Partial_Soft_Credit__c>();

        // Validation and preparation phase
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);

            // Basic Validations
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found for request.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive.');
            }
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Contact cannot be the primary contact of the opportunity.');
            }
            if (req.amount > (opp.Amount == null ? 0 : opp.Amount)) {
                throw new SoftCreditException('Partial soft credit amount cannot exceed the total opportunity amount.');
            }

            // Contact Role Validation
            String key = req.opportunityId + '-' + req.contactId;
            List<OpportunityContactRole> roles = ocrMap.get(key);
            OpportunityContactRole targetRole = null;
            Integer matchCount = 0;

            if (roles != null) {
                for (OpportunityContactRole ocr : roles) {
                    if (ocr.Role == req.role) {
                        targetRole = ocr;
                        matchCount++;
                    }
                }
            }

            if (matchCount != 1) {
                throw new SoftCreditException('Contact must have exactly one OpportunityContactRole with the role: ' + req.role);
            }

            // Map to Existing Record or Create New
            npsp__Partial_Soft_Credit__c psc = pscMap.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c();
                psc.npsp__Opportunity__c = req.opportunityId;
                psc.npsp__Contact__c = req.contactId;
            }

            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = targetRole.Id;

            toUpsert.add(psc);
        }

        // Final DML operation
        if (!toUpsert.isEmpty()) {
            upsert toUpsert;
        }
    }
}
