/**
 * Service class to handle NPSP Family relationship linking.
 * 
 * NPSP Relationship reciprocity is configured to "List Setting". When a relationship 
 * of type 'Parent' is created, NPSP triggers automatically create the reciprocal 
 * relationship (Son, Daughter, or Child) based on the child's gender as defined 
 * in the Relationship Lookup settings.
 */
public with sharing class FamilyService {

    /**
     * Links parents to children in NPSP.
     * 
     * @param parentIdByChildId Map where keys are Child Contact Ids and values are Parent Contact Ids.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all unique Contact Ids involved to optimize the SOQL query
        Set<Id> allIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            allIds.add(childId);
            allIds.add(parentIdByChildId.get(childId));
        }

        // Identify existing relationships between any of the pairs to prevent duplicates.
        // We use a direction-independent key (sorted IDs) to check for any existing link.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c 
            FROM npe4__Relationship__c 
            WHERE npe4__Contact__c IN :allIds OR npe4__RelatedContact__c IN :allIds
        ]) {
            existingPairs.add(createPairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> relationshipsToInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String pairKey = createPairKey(childId, parentId);

            // Skip if any relationship (regardless of type or direction) already exists
            if (!existingPairs.contains(pairKey)) {
                // Creating the 'Parent' relationship triggers NPSP to create the 
                // reciprocal (Son/Daughter/Child) automatically via triggers.
                relationshipsToInsert.add(new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
                ));

                // Add to the set to prevent creating duplicate pairs within the same batch
                existingPairs.add(pairKey);
            }
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    /**
     * Generates a unique, direction-independent key for a pair of Contact Ids.
     */
    private static String createPairKey(Id id1, Id id2) {
        return (id1 < id2) ? (String)id1 + (String)id2 : (String)id2 + (String)id1;
    }
}
