/**
 * Service class to handle the reassignment of Account and associated Contact ownership.
 */
public with sharing class AccountOwnershipService {

    /**
     * Reassigns the specified Accounts and all their associated Contacts to a new owner.
     * 
     * This method ensures that Account trigger actions are bypassed during the update
     * to prevent expensive territory recalculations, while allowing Contact trigger
     * actions to execute normally.
     * 
     * @param accountIds Set of Account IDs to be reassigned.
     * @param newOwnerId The ID of the user who will become the new owner.
     * @throws DmlException if any of the updates fail (all-or-none).
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Bypass Account trigger actions using the Trigger Actions Framework (TAF)
        TriggerBase.bypass(Account.SObjectType);

        try {
            // Prepare Accounts for update without needing a SOQL query
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accId : accountIds) {
                accountsToUpdate.add(new Account(
                    Id = accId, 
                    OwnerId = newOwnerId
                ));
            }

            // Query all Contacts associated with the provided Accounts (SOQL #1)
            List<Contact> contactsToUpdate = [
                SELECT Id 
                FROM Contact 
                WHERE AccountId IN :accountIds
            ];

            for (Contact con : contactsToUpdate) {
                con.OwnerId = newOwnerId;
            }

            // Update Accounts (DML #1) - Trigger actions bypassed
            update accountsToUpdate;

            // Update Contacts (DML #2) - Trigger actions execute normally
            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }
        } finally {
            // Ensure Account automation is restored for the remainder of the transaction
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
